create table public.mastery_records (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.profiles(id) on delete cascade, competency_id uuid not null references public.competencies(id) on delete restrict, mastery_score numeric(6,2) not null default 0 check (mastery_score between 0 and 100), mastery_level integer not null default 0 check (mastery_level >= 0), evidence_count integer not null default 0 check (evidence_count >= 0), last_evaluated_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (student_id, competency_id));;
